'use strict';
const disk={project:null,cache:'',family:'',owner:'',version:'',status:'',pivot:'works',metric:'recorded_file_bytes',color:'status',q:'',offset:0,rows:[],live:null};
const diskColors={'selected':'#3b7959','current':'#6f9d81','known-reference':'#145947','protected':'#8a73aa','metadata':'#6a93b4','history':'#8da5b2','deprecated':'#cf9456','unknown':'#b4b8b0'};
const diskLabels={'selected':'Observed selected','current':'Observed current','known-reference':'Named in Git snapshot','protected':'Observed pinned / leased','metadata':'Registry metadata','history':'Observed history','deprecated':'Deprecated references','unknown':'Unknown'};
function drawStorageNavigation(){drawWorkNavigation();document.querySelector('.toolbar').hidden=true;$('work-controls').hidden=true;$('heading').textContent=disk.project?'Storage · '+currentProject().label:'Storage · all projects';$('subheading').textContent='Explore retained observations by cache, object, work or version.';$('assets').className='storage-layout';$('category-heading').textContent='Cache inventory';$('result-count').textContent='';$('more').hidden=true;}
async function openStorage(){window.scrollTo(0,0);close();state.project='all';state.mode='storage';state.q='';$('search').value='';disk.project=null;drawNavigation();await loadGlobalStorage();}
function diskSelect(label,value,options,change){const wrap=node('label','disk-filter');wrap.append(node('span','',label));const s=node('select');s.setAttribute('aria-label',label);options.forEach(([v,t])=>s.append(new Option(t,v)));s.value=value;s.onchange=()=>change(s.value);wrap.append(s);return wrap;}
function diskMetric(summary){return summary?.[disk.metric]||0;}
function diskHue(key){let n=0;for(const c of key)n=(n*31+c.charCodeAt(0))>>>0;return'hsl('+(n%360)+' 28% 55%)';}
function diskColor(group){if(disk.color==='status'){const states=Object.entries(group.summary.states);states.sort((a,b)=>(b[1][disk.metric]||0)-(a[1][disk.metric]||0));return diskColors[states[0]?.[0]]||diskColors.unknown;}const a=disk.color==='version'?(disk.pivot==='versions'?[group.key]:group.summary.versions):disk.color==='work'?(disk.pivot==='works'?[group.key]:group.summary.owners):group.summary.tiers.map(String);return diskHue(a.length===1?a[0]:'Shared / multiple');}
function diskTreemap(groups){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 1000 180');svg.setAttribute('role','img');svg.setAttribute('aria-label','Largest groups sized by '+(disk.metric==='recorded_file_bytes'?'recorded file bytes':'measured allocation'));const items=groups.filter(g=>diskMetric(g.summary)>0);function paint(list,x,y,w,h){if(!list.length)return;if(list.length===1){const g=list[0];const rect=document.createElementNS(svg.namespaceURI,'rect');Object.entries({x:x+1,y:y+1,width:Math.max(0,w-2),height:Math.max(0,h-2),fill:diskColor(g),rx:3}).forEach(([k,v])=>rect.setAttribute(k,v));const tip=document.createElementNS(svg.namespaceURI,'title');tip.textContent=g.key+' · '+bytes(diskMetric(g.summary));rect.append(tip);rect.style.cursor='pointer';rect.onclick=()=>{if(disk.pivot==='versions')disk.version=g.key;else if(disk.pivot==='works'&&g.key!=='Unattributed')disk.owner=g.key;else disk.q=g.key;disk.offset=0;loadStorage();};svg.append(rect);if(w>100&&h>36){const text=document.createElementNS(svg.namespaceURI,'text');text.setAttribute('x',x+9);text.setAttribute('y',y+22);text.setAttribute('fill','#fff');text.setAttribute('font-size','12');text.setAttribute('pointer-events','none');const label=g.key.split('/').at(-1);text.textContent=label.slice(0,Math.floor(w/7)-2);svg.append(text);}return;}const total=list.reduce((n,g)=>n+diskMetric(g.summary),0);let n=1,sum=diskMetric(list[0].summary);while(n<list.length-1&&sum+diskMetric(list[n].summary)<total/2){sum+=diskMetric(list[n++].summary);}const ratio=sum/total;if(w>=h){paint(list.slice(0,n),x,y,w*ratio,h);paint(list.slice(n),x+w*ratio,y,w*(1-ratio),h);}else{paint(list.slice(0,n),x,y,w,h*ratio);paint(list.slice(n),x,y+h*ratio,w,h*(1-ratio));}}paint(items,0,0,1000,180);return svg;}
function drawDisk(d){const area=$('assets');area.replaceChildren();const back=node('button','button secondary','← All projects & drives');back.onclick=openStorage;area.append(back);const objectsBack=node('button','button secondary','Manage project objects');objectsBack.onclick=()=>openObjectManager(disk.project);area.append(objectsBack);const time=d.observed_at?new Date(d.observed_at*1000).toLocaleString():'Observation time unknown';const banner=node('div','disk-banner');banner.append(node('strong','',(d.source.kind==='registered-object-metadata'?'Registered objects · ':'Retained inventory · ')+time),node('p','',(d.source.kind==='registered-object-metadata'?'Scope: '+(d.source.family||'all admitted works')+'. Named registered files only; no directory scan or payload verification. '+d.source.objects_not_observed+' registered objects not observed in probed stores. ':'This is a historical observation, not a fresh cache scan. ')+ 'Removal is not authorized. '+(d.source_coverage_complete?'':'Coverage is incomplete.')));area.append(banner);
 const stats=document.querySelector('.stats');stats.replaceChildren();[[bytes(d.summary.recorded_file_bytes),'recorded file bytes'],[bytes(d.summary.observed_allocated_bytes),'observed file allocation · alias coverage partial'],[fmt.format(d.summary.copies_with_unknown_allocation),'copies with unknown allocation or identity'],[bytes(d.summary.historical_review_allocation),d.summary.review_objects+' copies in historical review estimate']].forEach(([v,label])=>{const e=node('div');e.append(node('span','',v),node('small','',label));stats.append(e);});
 const filters=node('div','disk-filters');const apply=(key,value)=>{disk[key]=value;disk.offset=0;loadStorage();};filters.append(diskSelect('Cache',disk.cache,[['','All observed caches'],...d.places.filter(p=>p.observed).map(p=>[p.label,p.label])],v=>apply('cache',v)),diskSelect('Family',disk.family,[['','All families'],...[...new Set([...d.families,...currentProject().collections.filter(c=>c.top_level!==false).map(c=>c.label)])].sort().map(f=>[f,f])],v=>changeStorageFamily(v,d)),diskSelect('Work',disk.owner,[['','All works'],...d.owners.map(o=>[o,o])],v=>apply('owner',v)),diskSelect('Status',disk.status,[['','All observed statuses'],['deprecated-refs','Has deprecated references'],['history-refs','Has previous-version references'],...Object.entries(diskLabels)],v=>apply('status',v)),diskSelect('Pivot',disk.pivot,[['works','By work'],['versions','By version'],['objects','By object']],v=>apply('pivot',v)),diskSelect('Size',disk.metric,[['recorded_file_bytes','Recorded file bytes'],['observed_allocated_bytes','Observed file allocation']],v=>apply('metric',v)),diskSelect('Color',disk.color,[['status','By status'],['cache','By cache'],['version','By version'],['work','By work']],v=>{disk.color=v;drawDisk(d);}));
 const search=node('input');search.type='search';search.placeholder='Filter hash or recorded version…';search.setAttribute('aria-label','Storage search');search.value=disk.q;search.onchange=()=>apply('q',search.value);filters.append(search);const clear=node('button','button secondary','Clear filters');clear.onclick=()=>{Object.assign(disk,{cache:'',owner:'',version:'',status:'',q:'',offset:0});changeStorageFamily('',d);};filters.append(clear);area.append(filters);
 if(disk.version){const chip=node('button','button secondary','Version: '+disk.version+' ×');chip.onclick=()=>apply('version','');area.append(chip);}
 const places=node('div','disk-places');d.places.forEach(p=>{const card=node('div','disk-place');card.append(node('h3','',p.label));const live=disk.live?.places.find(l=>l.label===p.label);if(live?.measured){card.append(node('p','',bytes(live.free)+' free at '+new Date(disk.live.measured_unix_seconds*1000).toLocaleTimeString()+' · '+bytes(live.total)+' volume'));const bar=node('div','disk-volume'),used=node('span');used.style.width=(100*(1-live.free/live.total))+'%';used.style.background=live.free/live.total<.05?'#b45a4e':live.free/live.total<.1?'#cf9456':'#61826e';bar.append(used);card.append(bar);}else card.append(node('p','muted',disk.live?'Live volume size unavailable / not probed':'Live volume capacity not measured'));card.append(node('p','',p.observed?(p.cache?bytes(p.cache.recorded_file_bytes)+' recorded file bytes in filter':'No matching copies within this observation and filter'):'Not observed in this inventory'));places.append(card);});area.append(places);const measure=node('button','button secondary','Measure live volume free space');measure.onclick=async()=>{const gen=state.generation;measure.disabled=true;try{const live=await api('/api/space',{project:state.project});if(gen!==state.generation||state.mode!=='storage')return;disk.live=live;drawDisk(d);}catch(e){notice(e.message);measure.disabled=false;}};area.append(measure);const refresh=node('button','button','Refresh registered objects'+(disk.family?' · '+disk.family:''));refresh.onclick=async()=>{const gen=state.generation;refresh.disabled=true;notice('Checking named registered files and sizes; no payload reads…');try{await api('/api/storage/observe',{project:state.project,snapshot:currentProject().commit,family:disk.family});if(gen!==state.generation||state.mode!=='storage')return;disk.cache='';disk.owner='';disk.version='';disk.status='';await loadStorage();}catch(e){notice(e.message);refresh.disabled=false;}};area.append(refresh);if(currentProject().retained_inventory&&d.source.kind!=='retained-inventory'){const retained=node('button','button secondary','Load retained whole-cache inventory');retained.onclick=async()=>{const gen=state.generation;retained.disabled=true;notice('Loading the exact retained inventory…');try{await api('/api/storage/retained',{project:state.project,snapshot:currentProject().commit});if(gen!==state.generation||state.mode!=='storage')return;Object.assign(disk,{cache:'',family:'',owner:'',version:'',status:'',q:''});await loadStorage();}catch(e){notice(e.message);retained.disabled=false;}};area.append(retained);}
 const chart=node('section','disk-chart');chart.append(node('h2','',disk.pivot==='versions'?'Largest recorded versions':disk.pivot==='objects'?'Largest observed objects':'Storage by work'),node('p','muted','Largest '+d.groups.length+' of '+fmt.format(d.groups_total)+' groups. Click a block to filter. '+(d.group_totals_overlap?'Objects shared by works or versions appear in multiple groups; these group totals are not additive.':'')),diskTreemap(d.groups));const legend=node('div','disk-legend');(disk.color==='status'?Object.entries(diskLabels):[]).forEach(([k,label])=>{const e=node('span');const swatch=node('i');swatch.style.background=diskColors[k];e.append(swatch,document.createTextNode(label));legend.append(e);});legend.append(node('span','muted',disk.color==='status'?'Color shows the largest status within each block.':'Color groups blocks by '+disk.color+'; shared groups use a common color.'));chart.append(legend);area.insertBefore(chart,places);
 const groups=node('div','disk-groups');d.groups.slice(0,20).forEach(g=>{const b=node('button','disk-group');b.append(node('span','',g.key),node('strong','',bytes(diskMetric(g.summary))),node('small','muted',fmt.format(g.summary.objects)+' objects'));const line=node('div','disk-group-bar');const max=diskMetric(d.groups[0]?.summary)||1;line.style.width=(100*diskMetric(g.summary)/max)+'%';line.style.background=diskColor(g);b.append(line);b.onclick=()=>{if(disk.pivot==='versions')disk.version=g.key;else if(disk.pivot==='works'&&g.key!=='Unattributed')disk.owner=g.key;else disk.q=g.key;disk.offset=0;loadStorage();};groups.append(b);});area.insertBefore(groups,chart);
 const objects=node('section','disk-objects');objects.append(node('h2','',fmt.format(d.objects_total)+' observed objects matching filters'),node('p','callout','The review estimate identifies historical copies worth rechecking in one cache. Current consumers, links, retained-copy hashes and custody still need fresh validation; safe reclaimable bytes remain unknown.'));const table=node('table');const head=node('tr');['Object','Observed status','File bytes / allocation','Recorded versions'].forEach(t=>head.append(node('th','',t)));table.append(head);disk.rows.forEach(o=>{const tr=node('tr');const id=node('td','mono',o.sha256.slice(0,16)+'…');id.title=o.sha256;const copies=o.copies.map(c=>(d.places.find(p=>p.tier===c.tier)?.label||('Tier '+c.tier))+': '+bytes(c.file_bytes)+' / '+(c.allocated_bytes==null?'unknown':bytes(c.allocated_bytes))).join('; ');tr.append(id,node('td','',o.known_reference?'Named in Git snapshot':diskLabels[o.state]||o.state),node('td','',copies),node('td','',o.versions.slice(0,3).join('\n')||'No recorded version reference'));table.append(tr);});objects.append(table);if(disk.rows.length<d.objects_total){const more=node('button','button secondary','Show more objects');more.onclick=()=>{disk.offset=disk.rows.length;loadStorage(true);};objects.append(more);}area.append(objects);$('result-count').textContent=fmt.format(d.objects_total)+' objects';document.querySelector('main footer').textContent=d.limitations;}
async function loadStorage(more=false){if(!disk.project){await loadGlobalStorage(more);return;}const gen=++state.generation;notice('');if(!more){disk.offset=0;disk.rows=[];$('assets').replaceChildren(node('div','empty','Reading the retained inventory and preparing storage pivots…'));}try{const p=currentProject();const d=await api('/api/storage',{project:p.id,snapshot:p.commit,cache:disk.cache,family:disk.family,owner:disk.owner,version:disk.version,state:disk.status,pivot:disk.pivot,metric:disk.metric,q:disk.q,offset:disk.offset});if(gen!==state.generation||state.mode!=='storage')return;disk.rows.push(...d.objects);drawDisk(d);}catch(e){if(gen!==state.generation||state.mode!=='storage')return;notice(e.message);$('assets').replaceChildren(node('div','empty','The enrolled observation could not be loaded. '+e.message));}}
